def mean_absolute_deviation(numbers: List[float]) -> float:
    """
    Given a list of input numbers, calculate the Mean Absolute Deviation
    around the mean of this dataset.
    """
    mean = sum(numbers) / len(numbers)
    abs_dev_sum = 0.0
    for num in numbers:
        abs_dev_sum += abs(num - mean)
    return abs_dev_sum / len(numbers)

