    dp = [[0 for _ in range(N)] for _ in range(N)]

    # Loop through the grid values and populate the dp table
    for i, j, value in grid_values:
        dp[i][j] = value

    # Loop through each row and column from the bottom-right to the top-left
    for i in range(N - 1, -1, -1):
        for j in range(N - 1, -1, -1):
            # If the current position is not the bottom-right corner, calculate the maximum sum of values collected on the two paths
            if i < N - 1 and j < N - 1:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
            # If the current position is the bottom-right corner, use the value at that position
            else:
                dp[i][j] = value

    # Return the maximum sum of values collected on the two paths
    return dp[0][0]
