def count_partitions(n, k, x):
    # Calculate the number of ways to partition n into k parts
    # where each part is at least x and order of parts does not matter
    num_partitions = 0
    for i in range(1, k + 1):
        num_partitions += binomial_coefficient(n, i) * (x ** i) * (n - i * x) ** (k - i)

    return int(num_partitions)


def binomial_coefficient(n, k):
    # Calculate the binomial coefficient C(n, k) = n! / (k! * (n - k)!)
    if k == 0 or n == k:
        return 1
    if k == 1 or n == 1:
        return n
    return binomial_coefficient(n - 1, k - 1) + binomial_coefficient(n - 1, k)


