def count_partitions(n, k, x):
    # Check if the parameters are valid
    if k <= 0 or x <= 0:
        return 0
    if n < k * x:
        return 0

    # Initialize the dp array
    dp = [0] * (n + 1)
    dp[0] = 1

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i - j * x >= 0:
                dp[i] += dp[i - j * x]

    return dp[n]

def count_partitions(n: int, k: int, x: int) -> int:
    # Initialize a dictionary to store the results of subproblems
    memo = {}

    # Base case: If n is 0, there is only one way to partition it into 0 parts
    if n == 0:
        return 1

    # If the result is already computed, return it from the memoization dictionary
    if (n, k) in memo:
        return memo[(n, k)]

    # Otherwise, compute the result recursively and store it in the memoization dictionary
    result = 0
    for i in range(x, n + 1):
        result += count_partitions(n - i, k - 1, i)

    memo[(n, k)] = result
    return result

