def min_remaining_space(V, n, volumes):
    # Initialize a 2D list to store the maximum occupied volume for each subset of items
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Populate the first row with the volumes of the items
    for i in range(1, n + 1):
        dp[i][0] = 0
        dp[i][i] = volumes[i - 1]

    # Loop through the remaining rows
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # Case 1: The current item does not fit in the box
            if volumes[i - 1] > V:
                dp[i][j] = dp[i - 1][j]

            # Case 2: The current item fits in the box
            else:
                # Case 2a: The current item is the last item
                if j == 1:
                    dp[i][j] = max(volumes[i - 1], dp[i - 1][j])

                # Case 2b: The current item is not the last item
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + volumes[i - 1])

    # Return the minimum remaining space
    return V - dp[n][n]

